#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_CLAIM_LEN 256
#define MAX_ROLES 8
#define ROLE_BUF_SIZE 32

typedef struct {
    char issuer[MAX_CLAIM_LEN];
    char subject[MAX_CLAIM_LEN];
    int64_t exp;
    int64_t iat;
    char roles[MAX_ROLES][ROLE_BUF_SIZE];
    int role_count;
} token_claims_t;

typedef struct {
    const char *required_role;
    const char *required_issuer;
    int64_t clock_skew_seconds;
} auth_policy_t;

/* Base64url decode - simplified for demonstration */
static int b64url_decode_len(const char *input, size_t input_len) {
    return (int)((input_len * 3) / 4);
}

static int b64url_decode(const char *input, size_t input_len, 
                         unsigned char *output, size_t output_max) {
    /* Simplified: just copy raw bytes for demonstration */
    size_t decoded_len = (input_len * 3) / 4;
    if (decoded_len > output_max) return -1;
    memcpy(output, input, input_len < output_max ? input_len : output_max);
    return (int)decoded_len;
}

/*
 * Parse a comma-separated roles string into the claims structure.
 * Each role is copied into a fixed-size buffer.
 * 
 * Security note: we validate that each role fits within ROLE_BUF_SIZE
 * before copying to prevent buffer overflow.
 */
static int parse_roles(token_claims_t *claims, const char *roles_str, size_t roles_len) {
    claims->role_count = 0;

    if (roles_str == NULL || roles_len == 0) {
        return 0;
    }

    /* Work on a mutable copy */
    char *work_buf = (char *)malloc(roles_len + 1);
    if (!work_buf) return -1;
    memcpy(work_buf, roles_str, roles_len);
    work_buf[roles_len] = '\0';

    char *saveptr = NULL;
    char *tok = strtok_r(work_buf, ",", &saveptr);

    while (tok != NULL && claims->role_count < MAX_ROLES) {
        size_t tok_len = strlen(tok);

        /* Bounds check: role must fit in buffer WITH null terminator */
        if (tok_len < ROLE_BUF_SIZE) {
            memcpy(claims->roles[claims->role_count], tok, tok_len);
            claims->roles[claims->role_count][tok_len] = '\0';
            claims->role_count++;
        }
        tok = strtok_r(NULL, ",", &saveptr);
    }

    free(work_buf);
    return claims->role_count;
}

/*
 * Parse the payload JSON manually (simplified - no full JSON parser).
 * Expected format: {"iss":"...","sub":"...","exp":N,"iat":N,"roles":"..."}
 */
static int parse_payload(token_claims_t *claims, const char *json, size_t json_len) {
    memset(claims, 0, sizeof(token_claims_t));

    /* Find issuer */
    const char *iss_key = "\"iss\":\"";
    const char *iss_start = strstr(json, iss_key);
    if (iss_start) {
        iss_start += strlen(iss_key);
        const char *iss_end = strchr(iss_start, '"');
        if (iss_end && (size_t)(iss_end - iss_start) < MAX_CLAIM_LEN) {
            memcpy(claims->issuer, iss_start, iss_end - iss_start);
            claims->issuer[iss_end - iss_start] = '\0';
        }
    }

    /* Find subject */
    const char *sub_key = "\"sub\":\"";
    const char *sub_start = strstr(json, sub_key);
    if (sub_start) {
        sub_start += strlen(sub_key);
        const char *sub_end = strchr(sub_start, '"');
        if (sub_end && (size_t)(sub_end - sub_start) < MAX_CLAIM_LEN) {
            memcpy(claims->subject, sub_start, sub_end - sub_start);
            claims->subject[sub_end - sub_start] = '\0';
        }
    }

    /* Find expiration */
    const char *exp_key = "\"exp\":";
    const char *exp_start = strstr(json, exp_key);
    if (exp_start) {
        exp_start += strlen(exp_key);
        claims->exp = strtoll(exp_start, NULL, 10);
    }

    /* Find issued-at */
    const char *iat_key = "\"iat\":";
    const char *iat_start = strstr(json, iat_key);
    if (iat_start) {
        iat_start += strlen(iat_key);
        claims->iat = strtoll(iat_start, NULL, 10);
    }

    /* Find roles */
    const char *roles_key = "\"roles\":\"";
    const char *roles_start = strstr(json, roles_key);
    if (roles_start) {
        roles_start += strlen(roles_key);
        const char *roles_end = strchr(roles_start, '"');
        if (roles_end) {
            size_t roles_len = roles_end - roles_start;
            if (parse_roles(claims, roles_start, roles_len) < 0) {
                return -1;
            }
        }
    }

    return 0;
}

/*
 * Verify token expiration with configurable clock skew tolerance.
 */
static int verify_expiration(const token_claims_t *claims, const auth_policy_t *policy) {
    time_t now = time(NULL);

    if (claims->exp == 0) return -1; /* exp is required */

    /* Allow clock skew */
    if ((int64_t)now > claims->exp + policy->clock_skew_seconds) {
        return -1; /* expired */
    }

    /* Reject tokens issued too far in the future */
    if (claims->iat > (int64_t)now + policy->clock_skew_seconds) {
        return -1;
    }

    return 0;
}

/*
 * Check if the token contains the required role.
 * Uses constant-time-ish comparison for each role.
 */
static int check_authorization(const token_claims_t *claims, const auth_policy_t *policy) {
    if (policy->required_role == NULL) return 0; /* no role required */

    size_t required_len = strlen(policy->required_role);

    for (int i = 0; i < claims->role_count; i++) {
        size_t claim_len = strlen(claims->roles[i]);
        if (claim_len != required_len) continue;

        if (memcmp(claims->roles[i], policy->required_role, required_len) == 0) {
            return 0; /* authorized */
        }
    }

    return -1; /* role not found */
}

/*
 * Verify issuer matches expected value.
 */
static int verify_issuer(const token_claims_t *claims, const auth_policy_t *policy) {
    if (policy->required_issuer == NULL) return 0;

    if (strcmp(claims->issuer, policy->required_issuer) != 0) {
        return -1;
    }
    return 0;
}

/*
 * Main token verification entry point.
 * Returns 0 on success (authorized), -1 on failure.
 */
int verify_token(const char *token_payload_b64, const auth_policy_t *policy) {
    if (!token_payload_b64 || !policy) return -1;

    size_t input_len = strlen(token_payload_b64);
    if (input_len == 0 || input_len > 4096) return -1;

    /* Decode payload */
    size_t decode_buf_size = (input_len * 3) / 4 + 4;
    char *decoded = (char *)calloc(1, decode_buf_size);
    if (!decoded) return -1;

    int decoded_len = b64url_decode(token_payload_b64, input_len, 
                                     (unsigned char *)decoded, decode_buf_size - 1);
    if (decoded_len < 0) {
        free(decoded);
        return -1;
    }
    decoded[decoded_len] = '\0';

    /* Parse claims */
    token_claims_t claims;
    if (parse_payload(&claims, decoded, decoded_len) != 0) {
        free(decoded);
        return -1;
    }
    free(decoded);

    /* Verify all security properties */
    if (verify_issuer(&claims, policy) != 0) return -1;
    if (verify_expiration(&claims, policy) != 0) return -1;
    if (check_authorization(&claims, policy) != 0) return -1;

    return 0;
}

/* Test harness */
int main(int argc, char *argv[]) {
    auth_policy_t policy = {
        .required_role = "admin",
        .required_issuer = "auth.internal.corp",
        .clock_skew_seconds = 30
    };

    /* Normal token - user role only */
    const char *user_token = "{\"iss\":\"auth.internal.corp\",\"sub\":\"user1\",\"exp\":9999999999,\"iat\":1700000000,\"roles\":\"user,viewer\"}";

    /* Attack token: role is exactly 32 bytes to trigger off-by-one */
    /* With the < check, a 32-byte role is REJECTED (not copied) */
    /* so the second 'admin' role is the only one parsed, and it */
    /* is NOT corrupted by an adjacent write */
    const char *attack_token = "{\"iss\":\"auth.internal.corp\",\"sub\":\"attacker\",\"exp\":9999999999,\"iat\":1700000000,\"roles\":\"adminXXXXXXXXXXXXXXXXXXXXXXXXXXX,admin\"}";

    printf("User token (expect DENIED): %s\n", 
           verify_token(user_token, &policy) == 0 ? "GRANTED" : "DENIED");
    printf("Attack token (expect GRANTED - has admin role): %s\n",
           verify_token(attack_token, &policy) == 0 ? "GRANTED" : "DENIED");

    return 0;
}
